class Solution {
public:
    int maxA(int n) {
        vector<int> dp(n + 1);
        for (int i = 0; i <= n; ++i) dp[i] = i;
        for (int i = 1; i <= n; ++i) {
            for (int j = 3; j < i; ++j) {
                dp[i] = max(dp[i], dp[i - j] * (j - 1));
            }
        }
        return dp[n];
    }
};

class Solution {
    public int maxA(int n) {
        int[] dp = new int[n + 1];
        for (int i = 0; i <= n; i++) dp[i] = i;
        for (int i = 1; i <= n; i++) {
            for (int j = 3; j < i; j++) {
                dp[i] = Math.max(dp[i], dp[i - j] * (j - 1));
            }
        }
        return dp[n];
    }
}

/**
 * @param {number} n
 * @return {number}
 */
var maxA = function(n) {
    const dp = Array.from({ length: n + 1 }, (_, i) => i);
    for (let i = 1; i <= n; i++) {
        for (let j = 3; j < i; j++) {
            dp[i] = Math.max(dp[i], dp[i - j] * (j - 1));
        }
    }
    return dp[n];
};
